'use strict';
const RELEASE='5.0.0', BUILD='nos-5.0.0-compact';
let lastSync='', updateAvailable=false, undoTask=null;
let wideSchedule=false;try{wideSchedule=localStorage.getItem('nos-wide-schedule')==='1';}catch{}
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const glyph={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',calendar:'M5 5h14v16H5z M8 2v6m8-6v6M5 11h14',tasks:'m3 6 2 2 3-4m3 2h10M3 13l2 2 3-4m3 2h10M3 20l2 2 3-4m3 2h10',study:'m2 8 10-5 10 5-10 5-10-5Zm4 3v6l6 3 6-3v-6m4-3v9',hockey:'m6 3 7 14h7v4H9L2 5m13-2-2 4',link:'m10 13 4-4m-7 6-2 2a3.5 3.5 0 0 0 5 5l4-4a3.5 3.5 0 0 0 0-5M10 11a3.5 3.5 0 0 1 0-5l4-4a3.5 3.5 0 0 1 5 5l-2 2',focus:'M12 3v4m0 10v4M3 12h4m10 0h4 M18 12a6 6 0 1 1-12 0 6 6 0 0 1 12 0Z',settings:'M4 6h16M4 12h16M4 18h16M8 3v6m8 0v6m-6 0v6',arrow:'M5 12h14m-6-6 6 6-6 6',external:'M8 4H4v16h16v-4M12 4h8v8m0-8L10 14',plus:'M12 5v14M5 12h14',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',left:'m14 5-7 7 7 7',right:'m10 5 7 7-7 7',edit:'m4 16 12-12 4 4L8 20H4v-4Zm9-9 4 4',trash:'M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7',logout:'M9 3H4v18h5m-1-9h13m-5-5 5 5-5 5',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',search:'M16 10a6 6 0 1 1-12 0 6 6 0 0 1 12 0Zm-1 5 6 6',menu:'M4 6h16M4 12h16M4 18h16',lock:'M6 10h12v11H6zM8 10V7a4 4 0 0 1 8 0v3'};
const icon=(n,cls='')=>`<svg class="ico ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${glyph[n]||glyph.home}"/></svg>`;
const tz='America/New_York';
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:tz,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const dateObj=d=>new Date(d+'T12:00:00');
const addDays=(d,n)=>{const v=dateObj(d);v.setDate(v.getDate()+n);return `${v.getFullYear()}-${String(v.getMonth()+1).padStart(2,'0')}-${String(v.getDate()).padStart(2,'0')}`;};
const fmt=(d,options={day:'numeric',month:'long'})=>dateObj(d).toLocaleDateString('ru-RU',options);
const weekDays=['Вс','Пн','Вт','Ср','Чт','Пт','Сб'];
const labels={class:'Учёба',hockey:'Хоккей',game:'Игра',personal:'Личное',routine:'Режим',travel:'Дорога',free:'Свободно',business:'Общество'};
const statuses={todo:'Не начато',doing:'В работе',done:'Готово'};
const taskKind=t=>t.kind||(t.course&&t.course!=='Личное'?'school':'personal');
const times=e=>e.start?(e.start+(e.end?'–'+e.end:'')):((e.timeLabel==='Время уточняется'?'Уточняется':e.timeLabel)||'Уточняется');
const eventTitle=t=>t.replace(/^CLASS — /,'').replace('ATHLETIC TRAINING — ','Athletic Training · ').replace('TEAM VIDEO — Video Session','Видеоразбор команды').replace(/^GAME — /,'');
const eventSort=e=>e.start||(/Before bed/i.test(e.timeLabel)?'23:59':/Morning/i.test(e.timeLabel)?'05:00':/Anytime|Daytime|Вне игры|Rest of day/i.test(e.timeLabel)?'12:00':'00:00');
const sortedEvents=d=>state.events.filter(e=>e.date===d).sort((a,b)=>eventSort(a).localeCompare(eventSort(b)));
let state,revision=0,view='home',selected=today(),month=today().slice(0,7),filter='active',search='',saving=false,installPrompt=null;
let offline=!navigator.onLine;
const navs=[['home','Расписание','home'],['calendar','Календарь','calendar'],['tasks','Домашнее и дела','tasks'],['study','Следующий семестр','study'],['hockey','Хоккейный центр','hockey'],['focus','Личный фокус','focus'],['links','Сайты и формы','link']];
function toast(m){undoTask=null;const t=$('#toast');t.textContent=m;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),5000);}
async function api(url,options={}){let r;try{r=await fetch(url,{...options,headers:{'Content-Type':'application/json',...options.headers},cache:'no-store'});}catch{throw Error('Нет связи с сервером. Изменения не сохранены — повтори после подключения.');}const b=await r.json();if(!r.ok){const e=Error(b.error||'Ошибка сервера');e.status=r.status;throw e;}return b;}
async function refresh(){const b=await api('/api/state');state=b.state;revision=b.revision;lastSync=new Date().toISOString();}
function chooseOpeningDay(){if(sortedEvents(today()).length){selected=today();}else{const dates=[...new Set(state.events.map(e=>e.date))].sort();selected=dates.find(d=>d>=today())||dates.at(-1)||today();}month=selected.slice(0,7);}
async function mutate(fn){if(saving){toast('Дождись сохранения предыдущего изменения.');return false;}saving=true;paintSync();const copy=structuredClone(state);try{fn(copy);const b=await api('/api/state',{method:'PUT',body:JSON.stringify({state:copy,revision})});state=copy;revision=b.revision;lastSync=new Date().toISOString();saving=false;render();return true;}catch(e){saving=false;if(e.status===409){await refresh().catch(()=>{});render();}if(e.status===401){state=null;login();}toast(e.message);paintSync();return false;}}
function paintSync(){const x=$('#sync');if(x){x.innerHTML=`<i class="${offline?'bad':''}"></i>${saving?'Сохраняю…':offline?'Нет сети':'Сохранено'}`;}}
async function boot(){try{const b=await api('/api/session');if(!b.authenticated)return login();await refresh();chooseOpeningDay();const route=location.hash.slice(1);view=navs.some(x=>x[0]===route)||route==='settings'?route:'home';render();}catch(e){$('#app').innerHTML=`<div class="offline"><div class="brand-mark">N</div><h1>${e.status===503?'Нужно настроить сервер':'Нужна связь с сервером'}</h1><p>${esc(e.status===503?e.message:'Личные данные не хранятся в офлайн-кэше.')}</p><button class="primary" data-action="retry">Повторить подключение</button></div>`;}}
function login(){state=null;$('#app').innerHTML=`<main class="premium-login"><a class="brand login-brand" href="#">N<span>/</span>OS</a><div class="login-orbit" aria-hidden="true"></div><section class="login-form"><div class="lock-mark">${icon('lock')}</div><h1>Личное пространство</h1><form id="login-form"><label class="sr-only" for="pin">Код доступа</label><input id="pin" type="password" name="pin" inputmode="numeric" pattern="[0-9]{8,12}" minlength="8" maxlength="12" autocomplete="current-password" placeholder="Код доступа" required><label class="inline-label"><input id="show-pin" type="checkbox"> Показать код</label><button class="primary wide" type="submit">Войти ${icon('arrow')}</button><p class="form-error" role="alert" id="login-error"></p></form><div class="login-security">${icon('lock')} Только для тебя</div></section><footer class="login-footer">NIKITA SOBOLEV <span>v${RELEASE}</span></footer></main>`;$('#show-pin').addEventListener('change',e=>$('#pin').type=e.target.checked?'text':'password');$('#login-form').addEventListener('submit',async e=>{e.preventDefault();const btn=e.target.querySelector('button');btn.disabled=true;$('#login-error').textContent='';try{await api('/api/login',{method:'POST',body:JSON.stringify({pin:$('#pin').value})});await refresh();chooseOpeningDay();render();}catch(err){$('#login-error').textContent=err.message;}finally{btn.disabled=false;}});}
function shell(content){return `<aside class="sidebar"><a href="#home" class="brand">N<span>/</span>OS</a><button class="icon-button mobile-nav-close" data-action="menu" aria-label="Закрыть меню">${icon('close')}</button><div class="side-label">ЛИЧНЫЙ ШТАБ / 05</div><nav>${navs.map(([id,label,i])=>`<button class="nav-item ${view===id?'active':''}" data-action="view" data-view="${id}">${icon(i)}<span>${label}</span>${view===id?'<i></i>':''}</button>`).join('')}</nav><div class="side-bottom"><div class="semester-note"><span>Текущий семестр</span><strong>Fall / 2026</strong><small>USJ · West Hartford</small></div><button class="nav-item ${view==='settings'?'active':''}" data-action="view" data-view="settings">${icon('settings')} Настройки и установка</button><div class="profile"><div class="avatar">НС</div><div><strong>Никита Соболев</strong><span>Личное пространство</span></div><button class="icon-button" data-action="logout" aria-label="Выйти">${icon('logout')}</button></div></div></aside><button class="sidebar-scrim" data-action="menu" aria-label="Закрыть меню"></button><div class="workspace"><header class="topbar"><button class="icon-button mobile-menu" data-action="menu" aria-label="Открыть меню">${icon('menu')}</button><div class="breadcrumb">Личный штаб <span>/</span> ${esc(navs.find(x=>x[0]===view)?.[1]||'Настройки')}</div><div class="top-actions">${quickMenu()}<span id="sync" class="sync"></span><button class="primary small global-event" data-action="add-event">${icon('plus')}<span>Событие</span></button></div></header><main id="main" class="route-${view}">${updateAvailable?`<div class="update-notice" role="status">Доступна новая версия <button class="secondary small" data-action="update-app">Обновить сайт</button></div>`:''}${content}</main><footer class="app-footer"><span>N / OS <b>Личное пространство.</b></span><span class="footer-version"><button class="text-button" data-action="view" data-view="settings">v${RELEASE}</button> · New York</span></footer></div>`;}
function render(){if(!state)return;$('#app').innerHTML=shell(({home:homePage,calendar:calendarPage,tasks:tasksPage,study:studyPage,links:linksPage,focus:focusPage,hockey:hockeyPage,settings:settingsPage}[view]||homePage)());paintSync();bindPage();document.title=`${navs.find(x=>x[0]===view)?.[1]||'Настройки'} · Nikita OS`;}
function heading(kicker,title,sub,action=''){return `<div class="page-heading"><div>${kicker?`<div class="eyebrow">${kicker}</div>`:''}<h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>${action}</div>`;}
function dayStrip(){const day=dateObj(selected).getDay(),monday=addDays(selected,-((day+6)%7));return `<div class="week-strip">${Array.from({length:7},(_,i)=>{const d=addDays(monday,i),ev=state.events.filter(e=>e.date===d&&e.type!=='free');return `<button class="day-cell ${d===selected?'selected':''} ${d===today()?'is-today':''}" data-action="day" data-date="${d}" aria-pressed="${d===selected}" aria-label="${esc(fmt(d))}"><span>${weekDays[dateObj(d).getDay()]}</span><strong>${dateObj(d).getDate()}</strong>${ev.some(e=>e.type==='game')?'<i class="game-dot" aria-label="Игра"></i>':''}</button>`;}).join('')}</div>`;}
const brandOptions=[['auto','Автоматически'],['bluejays','USJ Blue Jays'],['usj','Университет USJ'],['business','Business Society'],['none','Без логотипа']];
function brandAsset(brand){return {bluejays:'/brands/usj-bluejays.png',usj:'/brands/usj-seal.png',business:'/brands/business-society.png'}[brand]||'';}
function eventTheme(e){return e.type==='game'?'match':/ATHLETIC TRAINING/i.test(e.title)?'athletic':e.type==='hockey'?'training':e.type==='business'?'society':e.important?'priority':e.type==='class'?'academic':'plain';}
function eventBrand(e){if(e.brand&&e.brand!=='auto')return e.brand;return ['match','athletic','training'].includes(eventTheme(e))?'bluejays':e.type==='class'?'usj':e.type==='business'?'business':'none';}
function linkBrand(l){if(l.brand&&l.brand!=='auto')return l.brand;return l.category==='Хоккей'?'bluejays':l.category==='Учёба'?'usj':/society|eboard|members/i.test(l.title)?'business':'none';}
function logo(brand,cls='brand-logo'){const src=brandAsset(brand);return src?`<img class="${cls}" src="${src}" alt="" width="36" height="36">`:'';}
function pinnedLinks(){return state.links.filter(l=>l.pinned);}
function linkMark(l){return logo(linkBrand(l),'shortcut-logo')||icon('external');}
function quickDock(){const links=pinnedLinks();return `<section class="quick-dock" aria-label="Быстрый доступ"><div class="quick-dock-heading"><span class="eyebrow">БЫСТРЫЙ ДОСТУП</span>${view==='links'?'<span class="muted">★ Избранное</span>':`<button class="text-button" data-action="view" data-view="links">Все ссылки ${icon('arrow')}</button>`}</div><div class="shortcut-grid">${links.slice(0,6).map(l=>`<a class="shortcut-card" href="${esc(l.url)}" target="_blank" rel="noopener noreferrer">${linkMark(l)}<strong>${esc(l.title)}</strong>${icon('external')}</a>`).join('')||`<button class="secondary" data-action="view" data-view="links">Выбрать избранные ссылки ★</button>`}</div></section>`;}
function quickMenu(){const links=pinnedLinks();return `<details class="quick-menu"><summary aria-label="Быстрый доступ">${icon('external')}<span>Быстрый доступ</span></summary><div class="quick-menu-panel"><div class="eyebrow">ИЗБРАННЫЕ САЙТЫ</div>${links.slice(0,8).map(l=>`<a href="${esc(l.url)}" target="_blank" rel="noopener noreferrer">${linkMark(l)}<strong>${esc(l.title)}</strong>${icon('external')}</a>`).join('')||'<p>Отметь нужные ссылки звёздочкой.</p>'}<button class="text-button" data-action="view" data-view="links">Управлять ссылками ${icon('arrow')}</button></div></details>`;}
function timeCell(e){if(!e.start)return `<span class="time-unknown">${esc(e.timeLabel==='Before bed'?'Перед сном':(e.timeLabel==='Время уточняется'?'Уточняется':e.timeLabel)||'Уточняется')}</span>`;return `<span class="time-start">${esc(e.start)}</span>${e.end?`<span class="time-separator" aria-hidden="true">–</span><span class="time-end">${esc(e.end)}</span>`:''}`;}
function currentEventIds(){return new Set(state.events.filter(e=>e.date===today()&&e.start&&e.end&&Planner.minutes(e.start)<=clockMinutes()&&Planner.minutes(e.end)>clockMinutes()).map(e=>e.id));}
function eventRows(events,compact=false){const active=currentEventIds();return events.length?`<div class="agenda">${events.map(e=>{const theme=eventTheme(e),brand=eventBrand(e),asset=brandAsset(brand),now=active.has(e.id),cat=theme==='athletic'?'Athletic Training':labels[e.type];return `<button class="agenda-row ${e.type} theme-${theme} ${e.important?'is-important':''} ${e.type==='free'?'muted-event':''} ${now?'is-now':''}" data-action="edit-event" data-id="${esc(e.id)}" aria-label="${esc(times(e)+'; '+eventTitle(e.title)+'; '+cat+(e.location?'; '+e.location:''))}" ${now?'aria-current="time"':''}><div class="event-time">${timeCell(e)}</div><div class="event-content">${logo(brand,'event-logo')}<span class="event-copy"><span class="event-indicators"><span class="now-label" ${now?'':'hidden'}>СЕЙЧАС</span>${e.important?'<span class="important-label">ВАЖНО</span>':''}</span><strong>${esc(eventTitle(e.title))}</strong>${e.notes&&!e.notes.startsWith('Перенесено из')?`<span class="event-note">${esc(e.notes)}</span>`:''}</span></div><span class="event-place">${esc(e.location&&e.location!=='—'?e.location:'—')}<small>${esc(cat)}</small></span>${asset?`<img class="event-watermark" src="${asset}" alt="" width="58" height="58">`:''}${icon('edit','row-edit')}</button>`;}).join('')}</div>`:`<div class="empty"><strong>На этот день пока нет записей</strong><button class="primary" data-action="add-event">${icon('plus')} Добавить событие</button></div>`;}
function taskRow(t){return `<div class="task-row ${t.status==='done'?'completed':''}"><button class="task-check ${t.status}" data-action="cycle-task" data-id="${esc(t.id)}" aria-label="${t.status==='done'?'Вернуть задачу':'Выполнить задачу'}: ${esc(t.title)}" aria-pressed="${t.status==='done'}">${t.status==='done'?icon('check'):''}</button><button class="task-copy" data-action="edit-task" data-id="${esc(t.id)}"><strong>${esc(t.title)}</strong><span>${esc(t.course||(taskKind(t)==='school'?'Предмет не указан':'Личное'))}${t.due?' · '+esc(fmt(t.due,{day:'numeric',month:'short'})):' · без срока'}${t.status==='doing'?' · В работе':''}</span></button><button class="icon-button task-edit" data-action="edit-task" data-id="${esc(t.id)}" aria-label="Изменить задачу">${icon('edit')}</button></div>`;}
function clockMinutes(){const parts=new Intl.DateTimeFormat('en-GB',{timeZone:tz,hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date());return Planner.minutes(parts);}
function momentPanel(){const m=Planner.moment(state.events,today(),clockMinutes());return `<div class="moment-bar" aria-label="Текущий план по времени Нью-Йорка"><span class="moment-kicker">${m.current?'СЕЙЧАС':'ДАЛЬШЕ'}</span><strong>${esc(eventTitle((m.current||m.next)?.title||'Записей с точным временем нет'))}</strong><span class="moment-when">${m.current?esc(times(m.current)):m.next?esc((m.next.date===today()?'':fmt(m.next.date,{day:'numeric',month:'short'})+' · ')+times(m.next)):''}</span><button class="icon-button" data-action="refresh-data" aria-label="Обновить данные">${icon('download')}</button></div>`;}
function dayContext(){return selected!==today()?`<div class="day-context"><span>Сегодня ${esc(fmt(today()))} · выбран ${esc(fmt(selected,{day:'numeric',month:'long'}))}</span><button class="text-button" data-action="today">К сегодня ${icon('arrow')}</button></div>`:'';}
function conflictPanel(events){const pairs=Planner.conflicts(events);return pairs.length?`<details class="conflict-notice"><summary>Пересечения по времени: ${pairs.length} · проверить</summary>${pairs.map(([a,b])=>`<p>${esc(times(a))} ${esc(eventTitle(a.title))}<br>↔ ${esc(times(b))} ${esc(eventTitle(b.title))}</p>`).join('')}<small>Свободное время и режим не учитываются. Это проверка записей, не оценка нагрузки.</small></details>`:'';}
function schoolGroups(rows){const days=[...new Set(rows.map(t=>t.due||''))];const order=d=>d===today()?'0':d&&d>today()?'1'+d:!d?'2':'3'+d;days.sort((a,b)=>order(a).localeCompare(order(b)));return days.map(d=>`<section class="school-day"><div class="task-day-heading"><h3>${d?esc(fmt(d,{weekday:'short',day:'numeric',month:'long'})):'Без срока'}</h3>${d===today()?'<span>Сегодня</span>':d===addDays(today(),1)?'<span>Завтра</span>':''}</div>${rows.filter(t=>(t.due||'')===d).map(taskRow).join('')}</section>`).join('');}
function homePage(){const events=sortedEvents(selected),open=state.tasks.filter(t=>t.status!=='done'),school=open.filter(t=>taskKind(t)==='school'),personal=open.filter(t=>taskKind(t)==='personal'),old=school.some(t=>t.due&&t.due<today());return `${quickDock()}<div class="home-jumps"><button class="text-button" data-action="jump-homework">${icon('study')} Домашнее <span class="count">${school.length}</span> ${icon('arrow')}</button><button class="text-button" data-action="view" data-view="tasks">Личные дела <span class="count">${personal.length}</span></button></div><div class="planner-layout ${wideSchedule?'wide-schedule':''}"><section class="panel schedule-panel full-schedule"><div class="schedule-heading"><div><span class="eyebrow">${esc(fmt(selected,{month:'long',year:'numeric'}))} · NEW YORK</span><h1>Расписание недели</h1></div><div class="schedule-actions"><button class="secondary layout-toggle" data-action="toggle-wide" aria-pressed="${wideSchedule}">${wideSchedule?'Рядом с домашним':'Во всю ширину'}</button><button class="primary" data-action="add-event">${icon('plus')} Событие</button></div></div><div class="schedule-week-nav"><div class="date-controls"><button class="icon-button" data-action="shift-week" data-n="-7" aria-label="Предыдущая неделя">${icon('left')}</button><strong>${esc(fmt(addDays(selected,-((dateObj(selected).getDay()+6)%7)),{day:'numeric',month:'short'}))} — ${esc(fmt(addDays(selected,6-((dateObj(selected).getDay()+6)%7)),{day:'numeric',month:'short'}))}</strong><button class="icon-button" data-action="shift-week" data-n="7" aria-label="Следующая неделя">${icon('right')}</button></div><div class="button-group"><button class="text-button" data-action="today">Сегодня</button><button class="text-button" data-action="view" data-view="calendar">Календарь ${icon('calendar')}</button></div></div>${dayStrip()}${momentPanel()}${dayContext()}${conflictPanel(events)}<div class="agenda-caption"><strong>${esc(fmt(selected,{weekday:'long',day:'numeric',month:'long'}))}</strong><span>${events.length} записей · все видны</span></div><div class="agenda-columns" aria-hidden="true"><span>ВРЕМЯ · ET</span><span>ПЛАН</span><span>МЕСТО</span><span></span></div>${eventRows(events)}<div class="schedule-foot"><span>Нажми строку для правки · время в Нью-Йорке</span><div class="schedule-legend"><span class="key-hockey">Хоккей</span><span class="key-class">Занятия</span><span class="key-athletic">Athletic Training</span><span class="key-game">Игры / важное</span></div></div></section><aside class="homework-rail" id="homework-list" tabindex="-1"><section class="panel school-panel"><div class="panel-head"><div><span class="eyebrow">УЧЁБА</span><h2>Домашнее</h2></div><span class="count">${school.length}</span></div><button class="primary homework-add" data-action="add-task" data-kind="school">${icon('plus')} Добавить задание</button>${old?'<p class="deadline-note">Есть перенесённые старые сроки. Проверь их — сами задания ниже не скрыты.</p>':''}${schoolGroups(school)||'<div class="empty compact">Открытых домашних заданий нет.</div>'}<button class="more-button" data-action="view" data-view="tasks">Открыть все задания ${icon('arrow')}</button></section><section class="panel personal-panel"><div class="panel-head"><h2>Простые дела</h2><span class="count">${personal.length}</span></div><form id="personal-quick-form" class="quick-personal-form"><label class="sr-only" for="personal-title">Личное дело</label><input id="personal-title" name="title" placeholder="Купить, позвонить, сделать…" required maxlength="300"><button class="primary" type="submit" aria-label="Добавить личное дело">${icon('plus')}</button></form>${personal.map(taskRow).join('')||'<div class="empty compact">Здесь пока свободно.</div>'}</section></aside></div>`;}
function calendarPage(){let first=month+'-01',offset=(dateObj(first).getDay()+6)%7,begin=addDays(first,-offset);const cells=Array.from({length:42},(_,i)=>{const d=addDays(begin,i),ev=state.events.filter(e=>e.date===d&&!['free','travel','routine'].includes(e.type)).sort((a,b)=>Number(b.type==='game')-Number(a.type==='game')||Number(!!b.important)-Number(!!a.important)||eventSort(a).localeCompare(eventSort(b))),tasks=state.tasks.filter(t=>t.due===d&&t.status!=='done');return `<button class="month-cell ${d.slice(0,7)!==month?'outside':''} ${d===selected?'selected':''}" data-action="calendar-day" data-date="${d}" aria-label="${esc(fmt(d))}; событий: ${ev.length}; задач: ${tasks.length}"><span class="month-number ${d===today()?'today-number':''}">${dateObj(d).getDate()}</span>${ev.length?`<span class="mobile-calendar-count">${ev.length} соб.</span>`:''}${ev.slice(0,2).map(e=>`<span class="calendar-event type-${e.type}">${esc(e.start||'TBA')} ${esc(eventTitle(e.title))}</span>`).join('')}${tasks.length?`<span class="calendar-task">${tasks.length} зад.</span>`:''}${ev.length>2?`<small>ещё ${ev.length-2}</small>`:''}</button>`;}).join('');return `${heading('MAKE ROOM FOR WHAT MATTERS','Календарь','Встречи, занятия и задачи. Часовой пояс — Нью-Йорк.',`<button class="primary" data-action="add-event">${icon('plus')} Событие</button>`)}<section class="panel"><div class="panel-head"><h2 class="capitalize">${esc(fmt(first,{month:'long',year:'numeric'}))}</h2><div class="button-group"><button class="secondary small" data-action="calendar-today">Сегодня</button><button class="icon-button" data-action="month" data-n="-1" aria-label="Предыдущий месяц">${icon('left')}</button><button class="icon-button" data-action="month" data-n="1" aria-label="Следующий месяц">${icon('right')}</button></div></div><div class="month-weekdays">${['ПН','ВТ','СР','ЧТ','ПТ','СБ','ВС'].map(x=>`<span>${x}</span>`).join('')}</div><div class="month-grid">${cells}</div></section><section class="panel calendar-agenda" id="day-agenda"><div class="panel-head"><h2 class="capitalize">${esc(fmt(selected,{weekday:'long',day:'numeric',month:'long'}))}</h2><button class="text-button" data-action="add-event">${icon('plus')} Добавить</button></div>${conflictPanel(sortedEvents(selected))}${eventRows(sortedEvents(selected))}${state.tasks.filter(t=>t.due===selected).length?`<div class="panel-head"><h3>Сдать в этот день</h3></div>${state.tasks.filter(t=>t.due===selected).map(taskRow).join('')}`:''}</section>`;}
function tasksPage(){const done=filter==='done',rows=state.tasks.filter(t=>done?t.status==='done':t.status!=='done').filter(t=>(t.title+' '+t.course).toLowerCase().includes(search.toLowerCase())),school=rows.filter(t=>taskKind(t)==='school'),personal=rows.filter(t=>taskKind(t)==='personal'),old=school.some(t=>t.due&&t.due<today());return `${heading('','Домашнее и дела','Все задания видны. Учебные — по срокам, личные — отдельно.',`<button class="primary" data-action="add-task" data-kind="school">${icon('plus')} Домашнее</button>`)}<div class="task-toolbar"><div class="filters">${[['active','Нужно сделать'],['done','Выполнено']].map(([id,l])=>`<button class="filter ${filter===id?'active':''}" data-action="filter" data-filter="${id}">${l}</button>`).join('')}</div><label class="search-box">${icon('search')}<input type="search" id="task-search" value="${esc(search)}" placeholder="Найти задание или предмет" aria-label="Поиск заданий"></label></div><div class="task-board"><section class="panel school-panel"><div class="panel-head"><h2>Домашние задания</h2><span class="count">${school.length}</span></div><details class="quick-add-homework"><summary>＋ Быстро добавить задание</summary><form id="school-quick-form" class="quick-task-form"><label class="sr-only" for="school-title">Учебное задание</label><input id="school-title" name="title" placeholder="Что задали?" required maxlength="300"><div class="quick-task-fields"><label><span>Предмет</span><input name="course" placeholder="Например, COMP 210" maxlength="100"></label><label><span>Сдать до</span><input name="due" type="date"></label><button class="primary" type="submit">${icon('plus')} Добавить</button></div></form></details>${old&&!done?'<p class="deadline-note">Сроки из старых записей сохранены. Проверь актуальность; ничего не спрятано и не удалено.</p>':''}<div id="task-list">${schoolGroups(school)||'<div class="empty compact">Нет заданий в этом списке.</div>'}</div></section><section class="panel personal-panel"><div class="panel-head"><h2>Простые дела</h2><span class="count">${personal.length}</span></div><form id="personal-quick-form" class="quick-personal-form"><label class="sr-only" for="personal-title">Личное дело</label><input id="personal-title" name="title" placeholder="Купить, позвонить, сделать…" required maxlength="300"><button class="primary" type="submit" aria-label="Добавить личное дело">${icon('plus')}</button></form>${personal.map(taskRow).join('')||'<div class="empty compact">Нет дел в этом списке.</div>'}</section></div><p class="page-note">Галочка — готово. Название — изменить. Внутри задания можно сохранить ссылку на Blackboard или Notion. Автоматической синхронизации нет.</p>`;}
function courseConflicts(){const list=[];for(let i=0;i<state.courses.length;i++)for(let j=i+1;j<state.courses.length;j++){let a=state.courses[i],b=state.courses[j];if(a.semester===b.semester&&a.start&&a.end&&b.start&&b.end&&a.start<b.end&&b.start<a.end&&a.days.some(d=>b.days.includes(d)))list.push([a,b]);}return list;}
function studyPage(){const conflicts=courseConflicts(),total=state.courses.reduce((n,c)=>n+c.credits,0),registered=state.courses.filter(c=>c.status==='registered');return `${heading('BUILD YOUR NEXT CHAPTER','Следующий семестр','Собери варианты курсов до регистрации в MyUSJ.',`<button class="primary" data-action="add-course">${icon('plus')} Добавить курс</button>`)}<div class="metric-grid"><div class="metric"><span>В плане</span><strong>${state.courses.length}<small>курсов</small></strong></div><div class="metric"><span>Всего в списке</span><strong>${total}<small>кредитов</small></strong></div><div class="metric"><span>Зарегистрировано</span><strong>${registered.length}<small>курсов</small></strong></div><div class="metric"><span>Пересечения</span><strong class="${conflicts.length?'warning':'lime'}">${conflicts.length}<small>пар курсов</small></strong></div></div>${conflicts.length?`<div class="notice warning">${conflicts.map(([a,b])=>`${esc(a.code||a.title)} ↔ ${esc(b.code||b.title)}`).join('<br>')}<br><small>Пересечение по дням и времени внутри одного семестра.</small></div>`:''}<div class="course-grid">${state.courses.map(c=>`<article class="panel course-card"><div class="course-top"><span class="eyebrow">${esc(c.semester||'Семестр не указан')}</span><button class="icon-button" data-action="edit-course" data-id="${esc(c.id)}" aria-label="Редактировать курс">${icon('edit')}</button></div><span class="course-code">${esc(c.code||'Курс')}</span><h2>${esc(c.title)}</h2><p>${esc(c.section?'Секция '+c.section+' · ':'')}${c.credits} кредитов</p><div class="course-time">${esc(c.days.map(d=>weekDays[d]).join(' / ')||'Дни не заданы')}<strong>${esc(c.start?c.start+'–'+c.end:'Время уточняется')}</strong><span>${esc(c.location)}</span></div><div class="course-bottom"><span class="status-label">${{planned:'В плане',registered:'Зарегистрирован',waitlist:'Лист ожидания'}[c.status]}</span><button class="text-button" data-action="course-schedule" data-id="${esc(c.id)}">В календарь ${icon('arrow')}</button></div></article>`).join('')||`<section class="panel empty wide-card">${icon('study')}<h2>Спланируй следующий семестр</h2><p>Добавь код курса, секцию, дни, время и кредиты.<br>Пересечения появятся автоматически.</p><button class="primary" data-action="add-course">Добавить первый курс</button></section>`}</div><div class="notice">Это планировщик, а не регистрационная система университета. Окончательную запись на курсы и наличие мест проверяй в <a href="https://www.my.usj.edu/ICS/Student/" target="_blank" rel="noopener noreferrer">MyUSJ ↗</a>.</div>`;}
function linksPage(){const cats=[...new Set(state.links.map(l=>l.category||'Другое'))];return `${heading('','Сайты и формы','Всё нужное — в один переход.',`<button class="primary" data-action="add-link">${icon('plus')} Добавить ссылку</button>`)}${quickDock()}<div class="compact-link-sections">${cats.map(cat=>`<section class="links-section"><div class="section-heading"><h2>${esc(cat)}</h2><span class="muted">${state.links.filter(l=>(l.category||'Другое')===cat).length}</span></div><div class="links-grid">${state.links.filter(l=>(l.category||'Другое')===cat).map(l=>`<article class="link-card ${l.pinned?'pinned':''}"><a href="${esc(l.url)}" target="_blank" rel="noopener noreferrer"><span class="link-symbol">${linkMark(l)}</span><span class="link-copy"><h3>${esc(l.title)}</h3><span>${esc(l.description||new URL(l.url).hostname)}</span></span>${icon('external')}</a><div class="button-group"><button class="pin-button ${l.pinned?'is-pinned':''}" data-action="pin-link" data-id="${esc(l.id)}" aria-pressed="${!!l.pinned}" aria-label="Избранное: ${esc(l.title)}">${l.pinned?'★':'☆'}</button><button class="icon-button" data-action="edit-link" data-id="${esc(l.id)}" aria-label="Изменить ссылку">${icon('edit')}</button></div></article>`).join('')}</div></section>`).join('')}</div>`;}

function focusPage(){return `${heading('INTENTION BEFORE ACTION','Личный фокус','Главное на сегодня. Пространство для больших планов.')}<form id="focus-form" class="focus-grid"><section class="panel form-panel"><div class="eyebrow">01 / СЕГОДНЯ</div><h2>Главное действие на сегодня</h2><p class="muted">${state.focus.date!==today()?'Прошлая запись: '+esc(fmt(state.focus.date))+'. Сохранение привяжет фокус к сегодняшнему дню.':'Фокус на '+esc(fmt(today()))}</p><label>Фокус дня<textarea name="main" rows="3" maxlength="4000" placeholder="Один следующий шаг, который зависит от меня">${esc(state.focus.main)}</textarea></label><h3>Ещё до трёх дел · необязательно</h3>${[0,1,2].map(i=>`<label class="priority-input"><span>0${i+1}</span><input name="p${i}" maxlength="500" value="${esc(state.focus.priorities[i]||'')}" placeholder="Если останутся силы и время"></label>`).join('')}<button class="primary" type="submit">${icon('check')} Сохранить фокус и заметки</button></section><div class="right-stack"><section class="panel form-panel"><div class="eyebrow">02 / ЗАПИСАТЬ И ОТПУСТИТЬ</div><h2>Быстрая заметка</h2><label class="sr-only" for="focus-notes">Заметки</label><textarea id="focus-notes" name="notes" rows="7" maxlength="20000" placeholder="Мысли, идеи и напоминания…">${esc(state.focus.notes)}</textarea></section><section class="panel form-panel"><div class="eyebrow">03 / ДАЛЬШЕ ГОРИЗОНТА</div><h2>Долгосрочно</h2><label class="sr-only" for="focus-goals">Долгосрочные цели</label><textarea id="focus-goals" name="goals" rows="7" maxlength="20000">${esc(state.focus.goals)}</textarea></section></div></form>`;}
function hockeyPage(){const games=state.events.filter(e=>e.type==='game'&&e.date>=today()).sort((a,b)=>a.date.localeCompare(b.date)),h=state.hockey,r=h.readiness.find(x=>x.date===today());return `${heading('','Хоккейный центр','Один ориентир перед льдом. Одна корректировка после.',`<a class="secondary" href="${esc(state.links.find(l=>l.title==='HOULI Calendar')?.url||'https://www.houlisports.com/')}" target="_blank" rel="noopener noreferrer">HOULI ${icon('external')}</a>`)}<div class="hockey-layout v4-hockey"><section class="panel form-panel mental-panel"><span class="eyebrow">ПЕРЕД ЛЬДОМ · НЕОБЯЗАТЕЛЬНО</span><h2>То, что я контролирую</h2><p class="muted">Не результат матча — своё следующее действие.</p>${h.focusDate?`<p class="small-note">Запись: ${esc(fmt(h.focusDate))}${h.focusDate!==today()?' · прошлый фокус, можно обновить':''}</p>`:'<p class="small-note">Прежние заметки сохранены. У них нет даты.</p>'}<form id="hockey-form"><label>Одно действие на льду<input name="role" maxlength="4000" value="${esc(h.role)}" placeholder="Первым включаться в борьбу"></label><label>Ключевое слово<input name="keyword" maxlength="200" value="${esc(h.keyword)}" placeholder="Например, спокойно"></label><label>Первое действие в смене<input name="leadership" maxlength="4000" value="${esc(h.leadership)}" placeholder="Что сделаю сразу после выхода"></label><details class="post-ice" ${h.worked||h.review?'open':''}><summary>После льда · коротко</summary><label>Что получилось?<textarea name="worked" rows="2" maxlength="4000" placeholder="Один конкретный момент">${esc(h.worked||'')}</textarea></label><label>Одна корректировка<input name="review" maxlength="4000" value="${esc(h.review)}" placeholder="Что попробую в следующий раз"></label></details><button class="primary" type="submit">${icon('check')} Сохранить на сегодня</button></form></section><div class="right-stack"><section class="panel"><div class="panel-head"><div><span class="eyebrow">КАЛЕНДАРЬ</span><h2>Ближайшие игры</h2></div>${logo('bluejays')}</div>${games.map(g=>`<button class="game-list-row" data-action="edit-event" data-id="${esc(g.id)}"><div><strong>${esc(fmt(g.date,{day:'numeric',month:'short'}))}</strong><small>${esc(times(g))}</small></div><span>${esc(eventTitle(g.title))}<small>${esc(g.location==='—'?'Место уточняется':g.location)}</small></span>${icon('arrow')}</button>`).join('')||'<div class="empty compact">Будущих игр в записях нет.</div>'}<div class="import-hint">Изменения вносятся вручную. Время игры уточни в HOULI.</div></section><section class="panel form-panel reset-panel"><span class="eyebrow">МЕЖДУ СМЕНАМИ</span><h2>Вернуться в игру</h2><p>Спокойный выдох → факт вместо оценки → ключевое слово → следующее действие.</p><p class="small-note">Необязательный ориентир. Оставь только то, что тебе подходит; можно обсудить с тренером.</p><a class="secondary" href="${esc(h.playlist)}" target="_blank" rel="noopener noreferrer">${icon('hockey')} Мой плейлист ${icon('external')}</a></section><details class="panel readiness-panel"><summary>Как я себя чувствую <span>Личная отметка · по желанию</span></summary><div class="form-panel"><p class="muted">Без общего рейтинга готовности. Эти отметки не определяют, можно ли тренироваться. При боли или недомогании обратись к специалисту команды.</p><form id="readiness-form">${[['sleep','Сон'],['energy','Энергия'],['freshness','Свежесть'],['mood','Настроение']].map(([k,label])=>`<label class="range-label">${label}<select name="${k}" required><option value="">Выбрать</option>${[1,2,3,4,5].map(n=>`<option value="${n}" ${n===r?.[k]?'selected':''}>${n} / 5</option>`).join('')}</select></label>`).join('')}<button class="secondary wide" type="submit">${r?'Обновить':'Сохранить'} отметку</button></form><div class="small-note">${r?'Сегодняшняя запись сохранена.':'Сегодня отметки нет.'} 1 — низко, 5 — высоко. Сравнивай только с собой.</div></div></details></div></div>`;}
function settingsPage(){return `${heading('','Настройки и установка','Данные сохраняются в Supabase.')}<section class="panel version-panel"><div><span class="eyebrow">УСТАНОВЛЕННАЯ ВЕРСИЯ</span><h2>Nikita OS ${RELEASE}</h2><p>Сборка ${BUILD}</p><p>Последняя загрузка / сохранение: ${esc(lastSync?new Date(lastSync).toLocaleTimeString('ru-RU',{timeZone:tz,hour:'2-digit',minute:'2-digit'}):'—')} ET. Другие устройства обновляются по запросу.</p></div><div class="button-group"><button class="secondary" data-action="check-update">Проверить обновление</button><button class="secondary" data-action="update-app">Перезагрузить интерфейс</button></div><p id="version-status" role="status"></p><a class="text-button" href="/update-check.html" target="_blank" rel="noopener">Проверка опубликованной сборки ↗</a></section><div class="settings-grid"><section class="panel form-panel"><div class="eyebrow">01 / УСТАНОВКА</div><h2>Приложение на главном экране</h2><p>Открой этот сайт по HTTPS в обычном браузере, не внутри Notion.</p><button class="primary" data-action="install">${icon('download')} Установить приложение</button><ol class="instruction-list"><li><strong>iPhone / iPad</strong><span>Safari → Поделиться → На экран «Домой» → Добавить. Если есть «Открывать как веб-приложение», включи.</span></li><li><strong>Android</strong><span>Chrome → ⋮ → Установить приложение / Добавить на главный экран.</span></li><li><strong>Windows / Mac</strong><span>Chrome или Edge → значок установки в адресной строке. На новых macOS: Safari → Файл → Добавить в Dock.</span></li></ol><p class="small-note">Магазин приложений не нужен. Вход по коду сохраняется на 30 дней. Для просмотра и редактирования личных данных нужен интернет.</p></section><section class="panel form-panel"><div class="eyebrow">02 / ДАННЫЕ</div><h2>Резервная копия</h2><p>Скачивай копию перед крупными изменениями. Она содержит личные данные — храни её приватно.</p><button class="secondary wide" data-action="export">${icon('download')} Скачать JSON-копию</button><label class="import-label">Восстановить из копии<input type="file" id="backup-file" accept="application/json,.json"></label><div class="notice">Импорт полностью заменяет текущие данные. Перед восстановлением приложение запросит подтверждение.</div><h3>Безопасность</h3><p class="small-note">Код задаётся в переменной APP_PIN в Vercel, а не в HTML. Для смены кода измени APP_PIN и перезапусти сервер: старые сессии выйдут автоматически.</p><button class="secondary wide" data-action="logout">${icon('logout')} Выйти на этом устройстве</button></section></div><section class="panel form-panel"><div class="eyebrow">03 / ЧТО ПЕРЕНЕСЕНО</div><h2>Твои исходные блоки</h2><p>Расписание 19–25 октября 2026 · ${state.tasks.length} задач · быстрые ссылки · персональный штаб · хоккейный центр.</p><p class="small-note">Notion, Blackboard и HOULI не синхронизируются автоматически. Изменения, которые старые HTML-виджеты хранили только в localStorage твоего браузера, недоступны этому приложению. Старые задания, их сроки и статусы нужно проверить. Исторические кампусные матчи и старые неподтверждённые времена не добавлены в актуальный календарь.</p></section>`;}
function input(label,name,value='',type='text',extra=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function textarea(label,name,value=''){return `<label>${label}<textarea name="${name}" rows="3" maxlength="4000">${esc(value)}</textarea></label>`;}
function select(label,name,options,value){return `<label>${label}<select name="${name}">${options.map(([v,l])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`;}
function daysInput(values=[]){return `<fieldset class="day-select"><legend>Дни недели</legend>${[1,2,3,4,5,6,0].map(d=>`<label><input type="checkbox" name="days" value="${d}" ${values.includes(d)?'checked':''}><span>${weekDays[d]}</span></label>`).join('')}</fieldset>`;}
let editorKind='',editorId='';
function openEditor(kind,id=''){editorKind=kind;editorId=id;let collection={event:'events',task:'tasks',course:'courses',link:'links'}[kind];const x=state[collection]?.find(x=>x.id===id)||{};let title={event:'Событие',task:'Задача',course:'Курс следующего семестра',link:'Сайт или форма','course-dates':'Добавить курс в календарь'}[kind];let body='';
 if(kind==='event')body=`${input('Название','title',x.title||'','text','required maxlength="300"')}${input('Дата','date',x.date||selected,'date','required')}<div class="form-two">${input('Начало (ET)','start',x.start||'','time')}${input('Окончание (ET)','end',x.end||'','time')}</div><p class="field-hint">Если время неизвестно, оставь поля пустыми.</p>${select('Категория','type',Object.entries(labels),x.type||'personal')}${select('Логотип события','brand',brandOptions,x.brand||'auto')}<label class="checkbox-field"><input type="checkbox" name="important" ${x.important?'checked':''}><span>Важное мероприятие — выделить в расписании</span></label>${input('Место','location',x.location||'','text','maxlength="300"')}${textarea('Заметка','notes',x.notes||'')}${!id?`<details class="repeat"><summary>Повторять по дням недели</summary>${daysInput([dateObj(selected).getDay()])}${input('Повторять до (включительно)','repeatUntil','','date')}<p class="field-hint">Без даты окончания будет создано одно событие. Максимум 200 повторов.</p></details>`:'<p class="field-hint">Правка относится только к выбранному событию.</p>'}`;
 if(kind==='task')body=`${input('Что нужно сделать','title',x.title||'','text','required maxlength="300"')}${select('Список','kind',[['school','Учебное задание'],['personal','Личное дело']],x.kind||taskKind(x))}<div class="form-two">${input('Предмет (для учебных)','course',x.course||'','text','maxlength="100"')}${input('Срок (необязательно)','due',x.due||'','date')}</div><details class="repeat"><summary>Дополнительно</summary><div class="form-two">${select('Статус','status',Object.entries(statuses),x.status||'todo')}${select('Приоритет','priority',[['normal','Обычный'],['high','Высокий']],x.priority||'normal')}</div>${input('Ссылка на задание','url',x.url||'','url','maxlength="2000" placeholder="https://…"')}${textarea('Заметки','notes',x.notes||'')}</details>`;
 if(kind==='course')body=`${input('Название курса','title',x.title||'','text','required maxlength="300"')}<div class="form-two">${input('Код курса','code',x.code||'','text','maxlength="100" placeholder="COMP 220"')}${input('Секция','section',x.section||'','text','maxlength="100"')}</div><div class="form-two">${input('Семестр','semester',x.semester||'Spring 2027','text','required maxlength="100"')}${input('Кредиты','credits',x.credits??3,'number','min="0" max="30" step="0.5" required')}</div>${daysInput(x.days||[])}<div class="form-two">${input('Начало (ET)','start',x.start||'','time')}${input('Окончание (ET)','end',x.end||'','time')}</div>${input('Аудитория / место','location',x.location||'','text','maxlength="300"')}${select('Статус регистрации','status',[['planned','В плане'],['registered','Зарегистрирован'],['waitlist','Лист ожидания']],x.status||'planned')}${textarea('Заметки','notes',x.notes||'')}`;
 if(kind==='link')body=`${input('Название','title',x.title||'','text','required maxlength="300"')}${input('Адрес','url',x.url||'','url','required maxlength="2000" placeholder="https://…"')}${input('Категория','category',x.category||'Учёба','text','maxlength="100"')}${input('Описание','description',x.description||'','text','maxlength="300"')}${select('Логотип','brand',brandOptions,x.brand||'auto')}<label class="checkbox-field"><input type="checkbox" name="pinned" ${x.pinned?'checked':''}><span>★ Быстрый доступ на главной и в верхнем меню</span></label>`;
 if(kind==='course-dates'){const c=state.courses.find(c=>c.id===id);body=`<p>${esc(c.code)} · ${esc(c.title)}</p><p class="field-hint">Создаст занятия по выбранным дням недели. Праздники и каникулы не исключаются автоматически.</p>${input('Первый день семестра','from','','date','required')}${input('Последний день семестра','until','','date','required')}`;}
 $('#editor').innerHTML=`<div class="dialog-head"><div><div class="eyebrow">${id?'EDIT YOUR PLAN':'MAKE IT HAPPEN'}</div><h2>${title}</h2></div><button class="icon-button" data-action="close-editor" aria-label="Закрыть">${icon('close')}</button></div><form id="editor-form"><div class="editor-fields">${body}<p class="form-error" id="editor-error" role="alert"></p></div><div class="dialog-footer">${id&&collection?`<button type="button" class="danger-button" data-action="delete" data-kind="${kind}" data-id="${esc(id)}">${icon('trash')} Удалить</button>`:'<span></span>'}<div class="button-group"><button type="button" class="secondary" data-action="close-editor">Отмена</button><button type="submit" class="primary">${kind==='course-dates'?'Добавить занятия':'Сохранить'}</button></div></div></form>`;$('#editor').showModal();if(kind==='event'&&!id){$('#editor [name=date]').addEventListener('change',e=>{if(e.target.value){const d=dateObj(e.target.value).getDay();$$('#editor [name=days]').forEach(el=>el.checked=Number(el.value)===d);}});}$('#editor-form').addEventListener('submit',saveEditor);}
async function saveEditor(e){e.preventDefault();const f=new FormData(e.target),val=k=>String(f.get(k)||'').trim(),id=editorId||crypto.randomUUID(),kind=editorKind;let record={id,title:val('title')},records=[];$('#editor-error').textContent='';
 try{
 if(['event','course'].includes(kind)&&val('end')&&(!val('start')||val('end')<=val('start')))throw Error('Укажи начало раньше окончания. Для ночного события создай две записи.');
 if(kind==='event'){record={...record,date:val('date'),start:val('start'),end:val('end'),timeLabel:val('start')?'':'Время уточняется',type:val('type'),location:val('location'),notes:val('notes'),series:'',important:f.has('important'),brand:val('brand')||'auto'};const old=state.events.find(x=>x.id===id);if(old)record.series=old.series;records=[record];if(!editorId&&val('repeatUntil')){const until=val('repeatUntil'),days=f.getAll('days').map(Number);if(until<record.date||until>addDays(record.date,730)||!days.length)throw Error('Выбери дни и дату окончания в пределах двух лет.');records=[];for(let d=record.date;d<=until;d=addDays(d,1))if(days.includes(dateObj(d).getDay()))records.push({...record,id:crypto.randomUUID(),date:d,series:id});if(records.length>200||!records.length)throw Error('Допустимо от 1 до 200 повторов. Сократи период.');}}
 if(kind==='task')record={...record,kind:val('kind')||'personal',due:val('due'),course:val('course'),status:val('status'),priority:val('priority'),url:val('url'),notes:val('notes')};
 if(kind==='course'){if((val('start')&&!val('end'))||(!val('start')&&val('end')))throw Error('Задай оба времени или оставь оба пустыми.');record={...record,code:val('code'),section:val('section'),semester:val('semester'),credits:Number(val('credits')),days:f.getAll('days').map(Number),start:val('start'),end:val('end'),location:val('location'),status:val('status'),notes:val('notes')};}
 if(kind==='link')record={...record,url:val('url'),category:val('category'),description:val('description'),pinned:f.has('pinned'),brand:val('brand')||'auto'};
 if(kind==='course-dates'){const c=state.courses.find(c=>c.id===editorId);if(!c.days.length||!c.start||!c.end)throw Error('Сначала задай дни недели и время в карточке курса.');if(val('until')<val('from')||val('until')>addDays(val('from'),400))throw Error('Проверь даты семестра (не более 400 дней).');records=[];for(let d=val('from');d<=val('until');d=addDays(d,1))if(c.days.includes(dateObj(d).getDay())&&!state.events.some(e=>e.series===c.id&&e.date===d))records.push({id:crypto.randomUUID(),title:[c.code,c.title].filter(Boolean).join(' · '),date:d,start:c.start,end:c.end,timeLabel:'',type:'class',location:c.location,notes:c.notes,series:c.id});if(records.length>200)throw Error('Слишком много занятий: сократи период.');if(!records.length)throw Error('Новых занятий нет: проверь даты или они уже добавлены.');}
 const btn=e.target.querySelector('[type=submit]');btn.disabled=true;
 const ok=await mutate(s=>{if(kind==='course-dates'){s.events.push(...records);return;}const col={event:'events',task:'tasks',course:'courses',link:'links'}[kind];if(kind==='event'&&!editorId)s.events.push(...records);else{const idx=s[col].findIndex(x=>x.id===id);if(idx>=0)s[col][idx]=record;else s[col].push(record);}});if(ok){$('#editor').close();toast(records.length>1?`Сохранено событий: ${records.length}`:'Сохранено на сервере.');}else btn.disabled=false;
 }catch(err){$('#editor-error').textContent=err.message;}
}
function bindPage(){
 for(const kind of ['school','personal'])$('#'+kind+'-quick-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target),title=String(f.get('title')||'').trim();if(!title)return;const task={id:crypto.randomUUID(),title,kind,course:String(f.get('course')||'').trim(),due:String(f.get('due')||''),status:'todo',priority:'normal',notes:'',url:''};if(await mutate(s=>s.tasks.push(task)))toast('Добавлено.');});
 $('#task-search')?.addEventListener('input',e=>{const p=e.target.selectionStart;search=e.target.value;render();$('#task-search').focus();$('#task-search').setSelectionRange(p,p);});
 $('#focus-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target);if(await mutate(s=>{s.focus={date:today(),main:f.get('main'),priorities:[0,1,2].map(i=>f.get('p'+i)),notes:f.get('notes'),goals:f.get('goals')};}))toast('Фокус и заметки сохранены.');});
 $('#hockey-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target);if(await mutate(s=>{for(const k of ['role','keyword','leadership','review','worked'])s.hockey[k]=String(f.get(k)||'');s.hockey.focusDate=today();}))toast('Игровой фокус сохранён.');});
 $('#readiness-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target),r={date:today()};for(const k of ['sleep','energy','freshness','mood'])r[k]=Number(f.get(k));if(await mutate(s=>{s.hockey.readiness=s.hockey.readiness.filter(x=>x.date!==today());s.hockey.readiness.push(r);}))toast('Отметка готовности сохранена.');});
 $('#backup-file')?.addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;if(file.size>2_000_000){toast('Максимум 2 МБ.');return;}try{const b=JSON.parse(await file.text());if(b.version!==1||!b.state)throw Error('Неизвестный формат резервной копии.');if(!confirm('Полностью заменить текущие данные? Сначала сохрани свою резервную копию.'))return;if(await mutate(s=>{for(const k of Object.keys(s))s[k]=b.state[k];}))toast('Резервная копия восстановлена.');}catch(err){toast(err.message);}});
}
document.addEventListener('click',async e=>{if(!e.target.closest('.quick-menu'))$$('.quick-menu[open]').forEach(x=>x.open=false);const button=e.target.closest('[data-action]');if(!button)return;const a=button.dataset.action,id=button.dataset.id;try{
 if(a==='retry')return boot();
 if(a==='menu'){$('.sidebar').classList.toggle('open');return;}
 if(a==='view'){view=button.dataset.view;location.hash=view;render();window.scrollTo({top:0,behavior:'smooth'});return;}
 if(a==='toggle-wide'){wideSchedule=!wideSchedule;try{localStorage.setItem('nos-wide-schedule',wideSchedule?'1':'0');}catch{}render();return;}
 if(a==='jump-homework'){const panel=$('#homework-list');panel?.scrollIntoView({behavior:'smooth',block:'start'});panel?.focus({preventScroll:true});return;}
 if(a==='today'){selected=today();month=selected.slice(0,7);return render();}
 if(a==='day'){selected=button.dataset.date;return render();}
 if(a==='calendar-day'){selected=button.dataset.date;render();$('#day-agenda').scrollIntoView({behavior:'smooth',block:'start'});return;}
 if(a==='shift-week'){selected=addDays(selected,Number(button.dataset.n));return render();}
 if(a==='nearest-day'){const dates=state.events.map(e=>e.date).sort();const d=dates.find(d=>d>=today())||dates.at(-1);if(d){selected=d;render();}else toast('Будущих событий нет. Добавь новое.');return;}
 if(a==='month'){const d=dateObj(month+'-01');d.setMonth(d.getMonth()+Number(button.dataset.n));month=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;return render();}
 if(a==='calendar-today'){selected=today();month=today().slice(0,7);return render();}
 if(a==='filter'){filter=button.dataset.filter;return render();}
 if(a.startsWith('add-')){openEditor(a.slice(4));if(a==='add-task'&&button.dataset.kind)$('#editor [name=kind]').value=button.dataset.kind;return;}
 if(a.startsWith('edit-'))return openEditor(a.slice(5),id);
 if(a==='course-schedule')return openEditor('course-dates',id);
 if(a==='close-editor')return $('#editor').close();
 if(a==='delete'){if(!confirm('Удалить эту запись? Действие нельзя отменить без резервной копии.'))return;const col={event:'events',task:'tasks',course:'courses',link:'links'}[button.dataset.kind];if(await mutate(s=>s[col]=s[col].filter(x=>x.id!==id))){$('#editor').close();toast('Запись удалена.');}return;}
 if(a==='pin-link'){if(await mutate(s=>{const l=s.links.find(l=>l.id===id);l.pinned=!l.pinned;}))toast('Быстрый доступ обновлён.');return;}
 if(a==='cycle-task'){const previous=state.tasks.find(t=>t.id===id)?.status;if(await mutate(s=>{const t=s.tasks.find(t=>t.id===id);t.status=t.status==='done'?'todo':'done';})){toast(previous==='done'?'Задача возвращена.':'Готово.');undoTask={id,status:previous};$('#toast').insertAdjacentHTML('beforeend','<button class="text-button" data-action="undo-task">Отменить</button>');}return;}
 if(a==='undo-task'&&undoTask){const u=undoTask;if(await mutate(s=>{const t=s.tasks.find(t=>t.id===u.id);if(t)t.status=u.status;}))toast('Действие отменено.');return;}
 if(a==='refresh-data'){if(saving)return;await refresh();render();toast('Данные загружены с сервера.');return;}
 if(a==='check-update'){return checkVersion(true);}
 if(a==='update-app'){await updateApp();return;}
 if(a==='logout'){await api('/api/logout',{method:'POST',body:'{}'});state=null;$('#editor').close();login();return;}
 if(a==='export'){const blob=new Blob([JSON.stringify({version:1,exportedAt:new Date().toISOString(),state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`nikita-os-backup-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}
 if(a==='install'){if(installPrompt){await installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;}else toast('На iPhone: Safari → Поделиться → На экран «Домой». На Android: меню Chrome → Установить приложение.');return;}
 }catch(err){toast(err.message);}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('.sidebar')?.classList.remove('open');$$('.quick-menu[open]').forEach(x=>x.open=false);}});
window.addEventListener('hashchange',()=>{const r=location.hash.slice(1);if((navs.some(n=>n[0]===r)||r==='settings')&&view!==r&&state){view=r;render();}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
window.addEventListener('online',()=>{offline=false;paintSync();if(!state)boot();});window.addEventListener('offline',()=>{offline=true;paintSync();});
window.addEventListener('pageshow',e=>{if(e.persisted)boot();});
async function checkVersion(manual=false){try{const r=await fetch('/version.json?t='+Date.now(),{cache:'no-store'});if(!r.ok)throw Error('Проверка недоступна');const v=await r.json();updateAvailable=v.build!==BUILD;const el=$('#version-status');if(el)el.textContent=updateAvailable?'На сервере другая сборка: '+v.version+'. Нажми «Перезагрузить интерфейс».':'На сервере и в браузере версия '+RELEASE+'.';if(updateAvailable){if(manual)toast('Есть другая сборка. Перезагрузи интерфейс в настройках.');else if(state&&view==='home'&&!$('.update-notice'))$('#main').insertAdjacentHTML('afterbegin','<div class="update-notice" role="status">Доступна другая сборка <button class="secondary small" data-action="update-app">Обновить сайт</button></div>');}else if(manual)toast('Установлена опубликованная версия '+RELEASE+'.');}catch{if(manual)toast('Не удалось проверить обновление. Проверь подключение.');}}
async function updateApp(){toast('Перезагрузка интерфейса…');try{if('caches' in window)for(const key of await caches.keys())if(key.startsWith('nikita-os-shell-'))await caches.delete(key);if('serviceWorker' in navigator){const reg=await navigator.serviceWorker.getRegistration();if(reg)await reg.update();}}catch{}location.replace('/?build='+BUILD+location.hash);}
if('serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js',{updateViaCache:'none'}).then(r=>r.update()).catch(()=>{});
window.addEventListener('focus',()=>checkVersion());
setInterval(()=>{if(state&&!document.hidden){if(view==='home'&&$('.moment-bar'))$('.moment-bar').outerHTML=momentPanel();const active=currentEventIds();$$('.agenda-row').forEach(row=>{const yes=active.has(row.dataset.id);row.classList.toggle('is-now',yes);if(yes)row.setAttribute('aria-current','time');else row.removeAttribute('aria-current');const label=row.querySelector('.now-label');if(label)label.hidden=!yes;});}},60000);
checkVersion();
boot();
